const Module=require('node:module');
const original=Module._resolveFilename;
const productRoots=['/workspace/scratch/72459b8886f9/pulse-refresh-174/packages/','/workspace/scratch/72459b8886f9/pulse-refresh-174/wasm/packages/'];
Module._resolveFilename=function(...args){
 const resolved=original.apply(this,args);
 if(productRoots.some(root=>resolved.startsWith(root))) throw new Error('Control must not load snapshot product bytes: '+resolved);
 return resolved;
};
process.on('exit',()=>{
 const files=Object.keys(require.cache).filter(p=>p.startsWith('/tmp/pulse-b6-07-latest-control/'));
 require('node:fs').writeFileSync('/tmp/b6-07-control-modules.json',JSON.stringify(files,null,2)+'\n');
});
